+      if (state.folderKey) state.folderKey.fill(0);
+      if (state.ipnsKeypair?.privateKey) state.ipnsKeypair.privateKey.fill(0);
+    }","path":"packages/sdk/src/state/folder-tree.ts","commit_id":"5f3922c05dd477100c06e7e108e4d0cb19161511","original_commit_id":"af424a7230bfc7be3f9d1e42637c32727ce2520e","user":{"login":"FSM1","id":12774278,"node_id":"MDQ6VXNlcjEyNzc0Mjc4","avatar_url":"https://avatars.githubusercontent.com/u/12774278?v=4","gravatar_id":"","url":"https://api.github.com/users/FSM1","html_url":"https://github.com/FSM1","followers_url":"https://api.github.com/users/FSM1/followers","following_url":"https://api.github.com/users/FSM1/following{/other_user}","gists_url":"https://api.github.com/users/FSM1/gists{/gist_id}","starred_url":"https://api.github.com/users/FSM1/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/FSM1/subscriptions","organizations_url":"https://api.github.com/users/FSM1/orgs","repos_url":"https://api.github.com/users/FSM1/repos","events_url":"https://api.github.com/users/FSM1/events{/privacy}","received_events_url":"https://api.github.com/users/FSM1/received_events","type":"User","user_view_type":"public","site_admin":false},"body":"Fixed in 5f3922c — `FolderTree.set()` now clones `folderKey` and `ipnsKeypair` buffers into internal copies. `clear()`/`delete()` only zero these internal copies, leaving caller-provided buffers untouched. This mirrors the same defensive-copy pattern applied to `CipherBoxClient` constructor in the previous commit.","created_at":"2026-03-20T12:36:47Z","updated_at":"2026-03-20T12:36:47Z","html_url":"https://github.com/FSM1/cipher-box/pull/296#discussion_r2965541643","pull_request_url":"https://api.github.com/repos/FSM1/cipher-box/pulls/296","_links":{"self":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2965541643"},"html":{"href":"https://github.com/FSM1/cipher-box/pull/296#discussion_r2965541643"},"pull_request":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/296"}},"reactions":{"url":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2965541643/reactions","total_count