196→   *
197→   * Maps SDK events (keyed by ipnsName) to store updates (keyed by folder id).
198→   * The SDK emits folderId = ipnsName, so we reverse-lookup to find the store's folder id.
199→   */
200→  subscribeToSdk: (client: CipherBoxClient) => {
201→    // Unsubscribe any existing subscription
202→    if (_folderSdkUnsubscribe) {
203→      _folderSdkUnsubscribe();
204→    }
205→
206→    _folderSdkUnsubscribe = client.on((event) => {
207→      switch (event.type) {
