+  // Publish IPNS record
+  await sdkCore.createAndPublishIpnsRecord({
+    ipnsPrivateKey: binIpns.privateKey,
+    ipnsName: binIpns.ipnsName,
+    metadataCid: cid,
+    sequenceNumber: BigInt(params.metadata.sequenceNumber),
+    encryptedIpnsPrivateKey: encryptedIpnsKey,
+    keyEpoch,
+  });
