    ipnsKeypair.privateKey.fill(0);

    return {
      fileMetaIpnsName: ipnsKeypair.ipnsName,
      ipnsRecord: {
        ipnsName: ipnsKeypair.ipnsName,
        recordBase64,
        metadataCid,
        encryptedIpnsPrivateKey: teeEncryptedIpnsPrivateKey,
        keyEpoch,
      },
      ipnsPrivateKeyEncrypted,
    };
